package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.uicore.FrontendPort;
import com.mhtextractor.uiport.Confirmer;
import com.mhtextractor.uiport.Uiport;
import java.io.File;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;

/** Application lifetime owner. IPC is the default; fallback is selected only by an explicit property. */
public final class UiportRuntime {
    private final AtomicReference<AppConfig> context=new AtomicReference<>(new AppConfig());
    private final Consumer<Runnable> ui;
    private FrontendPort port;
    private AutoCloseable resource;
    private UiportRuntime(Consumer<Runnable> ui){this.ui=ui;}
    public static void start(String locale,Confirmer confirmer,Consumer<Runnable> ui,
                             Consumer<UiportRuntime> ready,Consumer<Throwable> failed){
        var owner=new UiportRuntime(ui);
        Thread.ofPlatform().daemon().name("frontend-startup").start(()->{
            try{owner.open(locale,confirmer);ui.accept(()->ready.accept(owner));}
            catch(Throwable error){owner.dispose();ui.accept(()->failed.accept(error));}
        });
    }
    private void open(String locale,Confirmer confirmer) throws Exception {
        String mode=System.getProperty("mht.uiport","ipc");
        Uiport implementation;
        if(mode.equals("inprocess")){
            var workspace=new BackendWorkspace(confirmer,context::get,Runnable::run);resource=workspace;implementation=workspace.port();
        }else if(mode.equals("ipc")){
            var ipc=new IpcUiport(confirmer,()->{
                var r=context.get();return new IpcUiport.RuntimeContext(r.isImageModeEnabled(),r.getInputFolder(),r.getOutputFolder(),r.isOpenFolderAfterComplete());
            });resource=ipc;
            String transport=System.getProperty("mht.backend.transport","executable");
            BackendSession.Command command;
            if(transport.equals("executable"))command=()->new ProcessBuilder(BackendExecutable.resolve().toString(),
                    "-Djava.io.tmpdir="+System.getProperty("java.io.tmpdir"),"--serve","--locale",locale)
                    .directory(Path.of(System.getProperty("java.io.tmpdir")).toFile());
            else if(transport.equals("jvm"))command=()->jvmCommand(locale);
            else throw new IllegalArgumentException("Unknown mht.backend.transport: "+transport);
            ipc.start(command,Duration.ofSeconds(20));implementation=ipc;
        }else throw new IllegalArgumentException("Unknown mht.uiport: "+mode);
        port=new FrontendPort(implementation,ui,context::set);port.bootstrap(context.get());
        System.out.println("GUI_PORT_IMPLEMENTATION="+implementation.getClass().getName()+" MODE="+mode);
    }
    private static ProcessBuilder jvmCommand(String locale) throws java.io.IOException {
        String cp=Arrays.stream(System.getProperty("java.class.path").split(File.pathSeparator))
                .filter(p->!new File(p).getName().matches("(?i)(javafx|atlantafx|ikonli).*"))
                .map(p->Path.of(p).toAbsolutePath().toString()).collect(java.util.stream.Collectors.joining(File.pathSeparator));
        Path root=Files.createTempDirectory(Path.of(System.getProperty("java.io.tmpdir")),"mht-frontend-");
        var args=List.of(Path.of(System.getProperty("java.home"),"bin/java.exe").toString(),"--limit-modules","java.se",
                "-Djava.io.tmpdir="+System.getProperty("java.io.tmpdir"),"-Dfile.encoding=UTF-8","-Dlogback.configurationFile=logback-headless.xml",
                "-cp",cp,"com.mhtextractor.backend.BackendCli","--serve","--locale",locale);
        Files.write(root.resolve("command.txt"),args);
        return new ProcessBuilder(args).directory(root.toFile()).redirectError(root.resolve("stderr.txt").toFile());
    }
    public FrontendPort port(){return Objects.requireNonNull(port);}
    public void closeAsync(Runnable finished){Thread.ofPlatform().daemon().name("frontend-shutdown").start(()->{dispose();ui.accept(finished);});}
    private void dispose(){
        try{if(port!=null)port.close();if(resource!=null)resource.close();}
        catch(Exception error){error.printStackTrace();}
    }
}
 * <h2>两种测试模式</h2>
 * <ul>
 *   <li>{@code -Dtest.mode=true}（默认）—— GUI 自动化：延迟 2s 后在 FX 线程跑
 *       {@code FeatureExercise.runAutomatedTests()}，把结果写 {@code logs/test-results.txt}，
 *       然后 {@code Platform.exit() + System.exit(0/1)}。<b>结果文件契约不变</b>：
 *       仍是 {@code === RESULTS: N passed, M failed ===} 行（{@code run-matrix.ps1} 校验它）。</li>
 *   <li>{@code -Dagent.exit.delay=<ms>} —— 追踪演练：跑 {@code exerciseAllFeatures()}，
 *       到点自尽。原先由 {@code App} 承载（native 可达性元数据采集用），P7 一并搬到这里。</li>
 * </ul>
 *
 * <p>⚠️ 它必须与 {@code target/classes} 一起出现在 classpath 上；<b>打进生产 jar 与 native 镜像
 * 的只有 {@code App}</b>，正式发行包不含本类。</p>
 *
 * <p>⚠️ 本类与 {@code App} 的装配是<b>有意重复</b>的：{@code App} 的装配顺序本身就是被测对象的一部分
 * （{@code NotificationHost} 的层序、{@code SidePanelHost} 的覆盖层都由它决定），
 * 把这段抽成共享工具会引入"测试跑的不是生产那段代码"的疑问。改 {@code App.start()} 的装配时，
 * 必须同步改这里。</p>
 */
public final class TestMain extends Application {

    /** 起窗口之后、开始驱动断言之前的稳定等待（毫秒）——与旧 {@code App} 的 2000ms 一致。 */
    private static final long AUTOMATION_DELAY_MS = 2000;

    /** 自动化总时限（毫秒）：超时强制退出 1，绝不允许测试 harness 永久挂住。 */
    private static final long AUTOMATION_WATCHDOG_MS = 300_000;

    private static String customCssUrl;

    @Override
    public void start(Stage primaryStage) throws Exception {
        // 与 App.start() 同：locale 必须在 FXMLLoader.load() 之前就绪
        GuiState guiState = GuiStateManager.load();
        if (guiState != null && guiState.getLocale() != null && !guiState.getLocale().isBlank()) {
            Locale locale = I18n.parseLocale(guiState.getLocale());
            if (locale != null) {
                I18n.setLocale(locale);
            }
        }

        var confirmer = new com.mhtextractor.gui.component.GuiConfirmer(() ->
                primaryStage.getScene() == null ? null : (javafx.scene.control.Label) primaryStage.getScene().lookup("#statusLabel"));
        com.mhtextractor.app.UiportRuntime.start(I18n.currentLocale().toLanguageTag(), confirmer, Platform::runLater,
                runtime -> {
                    try { finishStart(primaryStage, runtime); }
                    catch (Exception error) { error.printStackTrace(); Platform.exit(); }
                }, error -> { error.printStackTrace(); Platform.exit(); });
    }

    private void finishStart(Stage primaryStage, com.mhtextractor.app.UiportRuntime runtime) throws Exception {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/com/mhtextractor/gui/view/MainView.fxml"));
        // P6-B：与 App.start() 同一行（逐行等价 —— 改一处必须改另一处，见类 javadoc）。
        // 控制器由此拿到 loader，从而能在 initialize() 里用 getNamespace() 构造 MainViewRefs。
        loader.setControllerFactory(_ -> new com.mhtextractor.gui.controller.MainController(loader, runtime.port(), runtime::closeAsync));
        loader.setResources(I18n.bundle());
        Parent root = loader.load();
        StackPane overlay = SidePanelHost.install(root);
        StackPane shell = new StackPane(overlay);
        Scene scene = new Scene(shell);
        NotificationHost.install(scene, shell);
        MainController controller = loader.getController();

        Application.setUserAgentStylesheet(new NordLight().getUserAgentStylesheet());
        customCssUrl = Objects.requireNonNull(getClass().getResource("/custom.css")).toExternalForm();
        scene.getStylesheets().add(customCssUrl);

        Rectangle2D screenBounds = Screen.getPrimary().getVisualBounds();
        primaryStage.setTitle(I18n.get("app.title"));
        primaryStage.setScene(scene);
        com.mhtextractor.gui.controller.ParamSidePanel.of((javafx.scene.Node)scene.lookup("#statusLabel"), runtime.port());
        primaryStage.setWidth(screenBounds.getWidth() * 0.80);
        primaryStage.setHeight(screenBounds.getHeight() * 0.85);
        primaryStage.setMinWidth(900);
        primaryStage.setMinHeight(650);
        primaryStage.centerOnScreen();
        primaryStage.show();

        String agentDelay = System.getProperty("agent.exit.delay");
        if (agentDelay != null) {
            // 步骤 6（需求 C3 / 决策 E）：演练已从 FeatureExercise 外迁至 AgentExercise，调用点随迁
            AgentExercise exercise = new AgentExercise(controller);
            exercise.exerciseAllFeatures();
            new java.util.Timer(true).schedule(new java.util.TimerTask() {
                @Override
                public void run() {
                    Platform.exit();
                    System.exit(0);
                }
            }, Long.parseLong(agentDelay));
            return;
        }

        if (!"true".equals(System.getProperty("test.mode"))) {
            // 既没给测试开关也没给演练延迟：什么都不驱动（不是 GUI 自动化的启动方式）
            System.err.println("[TestMain] neither -Dtest.mode=true nor -Dagent.exit.delay=<ms> given"
                    + " - window is up but no test will run");
            return;
        }

        // 超时保护：自动化若挂住，进程必须自己退出，不能堵住复验流水线
        Thread watchdog = new Thread(() -> {
            try {
                Thread.sleep(AUTOMATION_WATCHDOG_MS);
            } catch (InterruptedException e) {
                return;
            }
            System.err.println("[TestMain] WATCHDOG: automated tests exceeded "
                    + AUTOMATION_WATCHDOG_MS + " ms - forcing exit 1");
            Runtime.getRuntime().halt(1);
        }, "test-mode-watchdog");
        watchdog.setDaemon(true);
        watchdog.start();

        new java.util.Timer(true).schedule(new java.util.TimerTask() {
            @Override
            public void run() {
                // 自动化测试直接操作 JavaFX 控件，必须回到 FX 线程执行
                Platform.runLater(() -> {
                    boolean success = new FeatureExercise(controller).runAutomatedTests();
                    Platform.exit();
                    System.exit(success ? 0 : 1);
                });
